            "Obligation de remboursement : le client devra rembourser intégralement de sa propre responsabilité.",
            "Action judiciaire et mesures légales : en cas de refus de remboursement ou d'absence de résolution, des actions seront engagées conformément aux lois sur la protection des consommateurs et au droit cybernétique applicables."
