            "18歳未満：出生登録の情報および写真のみでアカウントを検証できます。後にNIDを更新する機会はありますが、出生登録の情報は永久にロックされます。",
            "注意：18歳以上でありながらNIDを回避するために誤った年齢を選択した場合、アカウントは検証されずブロックされることがあります。同一の書類で二つ目のアカウントを作成しようとする試みは取り消されます。"
